  ('371802891276420481', 'Betty Boop and the Little King', 1936, 'Animation', 'Dave Fleischer', null, 'Mae Questel', null, 'Betty encounters The Little King when, bored by the opera, he sneaks out to join in with her rodeo routine.', 'Betty encounters The Little King when, bored by the opera, he sneaks out to join in with her rodeo routine.', 'https://image.tmdb.org/t/p/w500/ei0VQCm6OvQDu60l6kVCkfENaFa.jpg', 'tmdb:movie:201148'),
  ('290525462099611727', 'Betty Boop for President', 1932, 'Comedy, Animation', 'Dave Fleischer', null, 'Mae Questel', null, 'Betty''s campaign tries to appeal to everyone. Real candidates are parodied, but campaign promises are a bit bizarre.', 'Betty''s campaign tries to appeal to everyone. Real candidates are parodied, but campaign promises are a bit bizarre.', 'https://image.tmdb.org/t/p/w500/tVOnKnMXXhWFLG2uydS2j6rOG09.jpg', 'tmdb:movie:156499'),
  ('533882992653380540', 'Betty Boop, M.D.', 1932, 'Comedy, Animation', 'Dave Fleischer', null, 'Mae Questel', null, 'Betty, Koko and Bimbo sell a weird concoction in their medicine show.', 'Betty, Koko and Bimbo sell a weird concoction in their medicine show.', 'https://image.tmdb.org/t/p/w500/sdhY9ShdfEn8Wp7YjZeMlDMEPcz.jpg', 'tmdb:movie:156493'),
